#!/usr/bin/env bash
set -euo pipefail
# Starfare design-doc commit: Syndicate BUY delivery model + craft speed.
# Run from repo root: gitserver@gitserver:/mnt/git-server/starfare  (does NOT push)
test -f docs/design.md || { echo "!! run me from the starfare repo root"; exit 1; }

# --- 1. edits (fail-loud, base64 anchors so UTF-8 is copy-safe) ---
python3 - <<'PYEOF'
import base64
banner = base64.b64decode("").decode("utf-8").rstrip("\n")
buysub = base64.b64decode("").decode("utf-8").rstrip("\n")
tune   = base64.b64decode("").decode("utf-8").rstrip("\n")

p="docs/design.md"; s=open(p,encoding="utf-8").read()
hdr="### Syndicate Public Transport\n"
assert s.count(hdr)==1, f"design.md: header count={s.count(hdr)} (expected 1)"
s=s.replace(hdr, banner+"\n", 1)
a7="\n## 7. Politics and Law: The Council, Legality, and Fines"
assert s.count(a7)==1, f"design.md: section-7 anchor count={s.count(a7)} (expected 1)"
s=s.replace(a7, "\n"+buysub+"\n\n---\n"+a7, 1)
assert s.count("Syndicate Delivery - the BUY side")+s.count("Syndicate Delivery — the BUY side")==1, "BUY subsection insert failed"
open(p,"w",encoding="utf-8").write(s)
print("design.md: Syndicate delivery (BUY) + supersede banner")

p2="docs/phase-1-tuning.md"; t=open(p2,encoding="utf-8").read()
tl="- **Transit ticks per edge** `[PROP]`: **2** on an open edge, **1** on a secured (owned) edge — territory security's mechanical payoff."
assert t.count(tl)==1, f"phase-1-tuning: transit-line anchor count={t.count(tl)} (expected 1)"
t=t.replace(tl, tl+"\n"+tune, 1)
assert t.count("Syndicate craft speed")==1, "craft-speed insert failed"
open(p2,"w",encoding="utf-8").write(t)
print("phase-1-tuning.md: Syndicate craft speed 300 ticks/hex")
PYEOF

# --- 2. commit (NO push) ---
git add docs/design.md docs/phase-1-tuning.md
git commit -m "docs: Syndicate BUY delivery model (scheduled deposit, straight-line, vanish-on-loss) + craft speed

Rule the BUY side of the Exchange as a scheduled delivery, not a simulated shipment:
on BUY the engine resolves the nearest waystation, computes arrivalTick = buyTick +
ceil(hexDistance x CRAFT_SPEED), debits qty*price now (single price #43, no fee),
records a pending delivery {cargo, destinationSystemId, arrivalTick} in state.shipments,
and deposits it on arrival. Destination lost in flight -> goods vanish (conservation-
clean, cash already spent). Persistence is the mid-flight handling (absolute arrival
tick). Two-tier transport boundary named: Syndicate = straight line, no risk/tolls/
routing (this slice); guild-routed = Phase 4. Craft speed 300 ticks/hex [FIRST-CUT].
Supersede the old SELL-side Syndicate-hauling model (SELL is instant, sec 5); flag the
instant-SELL vs no-free-movement / vehicle-gate tension as an open thread, not resolved."

echo; echo "Done. Review: git show --stat HEAD ; then: git push origin main"
